const { incident_id, company_id, severity, category, description, site_id } = $input.first().json.body || $input.first().json;

const classification = {
  incident_id,
  company_id,
  suggested_severity: severity || 'medium',
  suggested_category: category || 'general',
  missing_fields: [],
  recommendations: [],
  ai_summary: '',
  confidence: 'medium'
};

if (!description) classification.missing_fields.push('description');
if (!site_id) classification.missing_fields.push('site_id');

classification.recommendations.push('Review incident details and verify classification');
classification.ai_summary = `Incident ${incident_id}: Requires human review. Category: ${classification.suggested_category}. Severity: ${classification.suggested_severity}.`;

return { json: classification };
